  // =========================================================================
  // 4. Deterministic Hash, Chronological Horizons & Canting Analyzer
  // =========================================================================
  function hashString(str) {
    let hash = 5381;
    for (let i = 0; i < str.length; i++) {
      hash = ((hash << 5) + hash) + str.charCodeAt(i);
      hash = hash & hash;
    }
    return Math.abs(hash);
  }

  const HORIZON_0_TITLES = new Set([
    'c_aachen', 'c_alexandria', 'c_antioch', 'c_athens', 'c_barcelona', 'c_byzantion', 'c_cologne', 'c_jerusalem', 'c_kent', 'c_kyiv', 'c_leon', 'c_lviv', 'c_mainz', 'c_metz', 'c_milano', 'c_paris', 'c_ravenna', 'c_roma', 'c_szekesfehervar', 'c_tarragona', 'c_thessaloniki', 'c_trier', 'c_venezia', 'c_wiltshire', 'c_york', 'd_alexandria', 'd_antioch', 'd_athens', 'd_barcelona', 'd_canterbury', 'd_latium', 'd_lombardy', 'd_ravenna', 'd_thessalonika', 'd_upper_lorraine', 'd_venice', 'd_wessex', 'e_byzantium', 'e_hre', 'h_roman_empire', 'k_asturias', 'k_danelaw', 'k_italy', 'k_leon', 'k_lotharingia', 'k_moravia', 'k_papal_state', 'k_romagna'
  ]);

  const HORIZON_1_EMPIRES = new Set(['e_germany', 'e_france']);
  const HORIZON_1_KINGDOMS = new Set([
    'k_germany', 'k_lotharingia', 'k_bavaria', 'k_italy', 'k_burgundy',
    'k_francia', 'k_aquitaine', 'k_east_francia', 'k_west_francia'
  ]);

  const HORIZON_2_EMPIRES = new Set(['e_britannia', 'e_carpathia']);
  const HORIZON_2_KINGDOMS = new Set([
    'k_england', 'k_bohemia', 'k_poland', 'k_denmark', 'k_croatia',
    'k_sicily', 'k_hungary', 'k_aragon', 'k_navarra', 'k_castille', 'k_valencia'
  ]);

  const HORIZON_3_EMPIRES = new Set([
    'e_scandinavia', 'e_russia', 'e_west_slavia', 'e_wendish_empire',
    'e_anatolia', 'e_macedonia', 'e_illyria', 'e_maghreb', 'e_africa',
    'e_aegyptus', 'e_oriens'
  ]);

  function getChronologicalHorizon(key, props, tier) {
    const k = (key || '').toLowerCase();
    if (HORIZON_0_TITLES.has(k)) return 0;
    const emp = props.empire || props.e_key || '';
    const kng = props.kingdom || props.k_key || '';
    if (HORIZON_1_EMPIRES.has(emp) || HORIZON_1_KINGDOMS.has(kng)) return 1;
    if (HORIZON_2_EMPIRES.has(emp) || HORIZON_2_KINGDOMS.has(kng)) return 2;
    if (HORIZON_3_EMPIRES.has(emp)) return 3;
    return 4;
  }

  // =========================================================================
  // 3a. Title Symbol Adoption Registry & Chronology Engine
  // =========================================================================

  let ADOPTION_REGISTRY = {};

  function loadAdoptionData(data) {
    if (data && typeof data === 'object') {
      ADOPTION_REGISTRY = data;
    }
  }

  function getCampaignEra(year) {
    if (year === null || year === undefined) return "Exterior Autonomous March (1194+)";
    if (year < 867) return "Classical & Pre-867 Antiquity";
    if (year <= 988) return "Carolingian & Lothringian Cradle (867–988)";
    if (year <= 1052) return "Tarraconian Ethnogenesis (989–1052)";
    if (year <= 1071) return "First Imperial Restoration (1053–1071)";
    if (year <= 1142) return "High Imperial Consolidation (1072–1142)";
    if (year <= 1194) return "Universal Roman Hegemony (1143–1194)";
    return "Exterior Autonomous March (1194+)";
  }

  function getAdoptionInfo(titleKey, props = {}, tier = 'county') {
    const k = (titleKey || '').toLowerCase();

    // 1. Check registry if loaded
    if (ADOPTION_REGISTRY && ADOPTION_REGISTRY[k]) {
      return Object.assign({}, ADOPTION_REGISTRY[k]);
    }

    // 2. Barony inheritance from parent county
    if (tier === 'barony' && props.county) {
      const cKey = (props.county || '').toLowerCase();
      if (ADOPTION_REGISTRY && ADOPTION_REGISTRY[cKey]) {
        const cInfo = ADOPTION_REGISTRY[cKey];
        return {
          tier: 'barony',
          county: cKey,
          year: cInfo.year,
          romanYear: cInfo.romanYear,
          yearDisplay: cInfo.yearDisplay,
          era: cInfo.era,
          saint: cInfo.saint,
          archetype: cInfo.archetype,
          historicalBasis: cInfo.historicalBasis,
          rationale: `Civic holding badge (Herren-Wâpen) established in ${cInfo.yearDisplay} under jurisdiction of Magistrat ${props.c_tarr || props.county}.`
        };
      }
    }

    // 3. Fallback deterministic heuristic engine (for offline or standalone use)
    const horizon = getChronologicalHorizon(k, props, tier);
    const isSino = k.startsWith('c_chi_') || k.startsWith('c_jap_') || props.c_hanzi || CANONICAL_SINOSPHERE_HANZI[k];

    let yr = 1154;
    let yrDisp = "1154 AD";
    let era = "Universal Roman Hegemony (1143–1194)";
    let rat = "";

    if (HORIZON_0_TITLES.has(k)) {
      yr = 800;
      yrDisp = "c. 800 AD (Adopted 1059 AD)";
      era = "Classical & Pre-867 Antiquity";
      rat = "Ancient civic insignia attested prior to 867 AD; formally codified as an imperial title symbol upon Carolingian and Ottonian consolidation.";
    } else if (horizon === 1) {
      yr = 1059;
      yrDisp = "1059 AD";
      era = "First Imperial Restoration (1053–1071)";
      rat = "Standardized as an imperial administrative title symbol during the 1059 Chancellery Codification under Kaiser Adémar 'the Great'.";
    } else if (horizon === 2) {
      yr = 1122;
      yrDisp = "1122 AD";
      era = "High Imperial Consolidation (1072–1142)";
      rat = "Adopted into the imperial administrative hierarchy during the High Imperial Consolidation era (Concordat of Worms).";
    } else if (horizon === 3) {
      yr = 1154;
      yrDisp = "1154 AD";
      era = "Universal Roman Hegemony (1143–1194)";
      rat = "Established as an imperial administrative title symbol during the 1154 Roman Hegemony expansion under Augustus Wernhard 'the Bear'.";
    } else {
      if (isSino) {
        yr = 1154;
        yrDisp = "1154 AD";
        era = "Universal Roman Hegemony (1143–1194)";
        rat = "Procedure 1 Sinitic Magistracy: Invested with the Vermilion Cinnabar Chop (Guóxī) in 1154 AD upon the establishment of the imperial East Asian prefecture.";
      } else {
        yr = 1176;
        yrDisp = "1176 AD";
        era = "Universal Roman Hegemony (1143–1194)";
        rat = "Frontier march insignia incorporated during the late 12th-century imperial administrative expansions.";
      }
    }

    return {
      tier: tier,
      year: yr,
      romanYear: yr,
      yearDisplay: yrDisp,
      era: era,
      saint: null,
      archetype: 'Administrative Magistracy',
      historicalBasis: '',
      rationale: rat
    };
  }

