  // 3b. Saint Holding Imagery Registry (Signa Sanctorum)
  // =========================================================================

  let SAINT_HOLDING_DATA = {};

  // Auto-load in Node.js environment if file exists on disk
  if (typeof require !== 'undefined' && typeof module !== 'undefined') {
    try {
      const fs = require('fs');
      const path = require('path');
      const p = path.join(__dirname, '../../data/saint_holding_imagery.json');
      if (fs.existsSync(p)) {
        SAINT_HOLDING_DATA = JSON.parse(fs.readFileSync(p, 'utf8'));
      }
    } catch (e) {}
  }

  function loadSaintData(data) {
    if (data && typeof data === 'object') {
      SAINT_HOLDING_DATA = Object.assign({}, SAINT_HOLDING_DATA, data);
    }
  }

  function getSaintHoldingInfo(titleKey) {
    const k = (titleKey || '').toLowerCase();
    return (SAINT_HOLDING_DATA && SAINT_HOLDING_DATA[k]) ? SAINT_HOLDING_DATA[k] : null;
  }

