    const hanziText = def.hanziChar || (def.hanzi ? (def.hanzi.length <= 2 ? def.hanzi : def.hanzi.substring(0, 2)) : '');
    const hanziColor = (def.field === 'or' || def.field === 'argent') ? PALETTE.sable : (def.chargeColor || PALETTE.or);
